import { forwardRef, type ButtonHTMLAttributes, type AnchorHTMLAttributes, type ReactNode } from 'react';

type ButtonVariant =
  | 'primary'
  | 'secondary'
  | 'tertiary'
  | 'destructive-primary'
  | 'destructive-secondary'
  | 'destructive-tertiary';

type ButtonSize = 'xs' | 's' | 'm' | 'l' | 'xl';

type ButtonBaseProps = {
  variant?: ButtonVariant;
  size?: ButtonSize;
  disabled?: boolean;
  loading?: boolean;
  animated?: boolean;
  iconLeft?: ReactNode;
  iconRight?: ReactNode;
  children: ReactNode;
  className?: string;
};

type ButtonAsButton = ButtonBaseProps &
  Omit<ButtonHTMLAttributes<HTMLButtonElement>, keyof ButtonBaseProps> & {
    href?: never;
  };

type ButtonAsAnchor = ButtonBaseProps &
  Omit<AnchorHTMLAttributes<HTMLAnchorElement>, keyof ButtonBaseProps> & {
    href: string;
  };

export type ButtonProps = ButtonAsButton | ButtonAsAnchor;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const Spinner = () => (
  <svg className="button__spinner-icon" width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <circle cx="8" cy="8" r="6" stroke="currentColor" strokeOpacity="0.25" strokeWidth="2" />
    <path d="M14 8a6 6 0 0 0-6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
  </svg>
);

export const Button = forwardRef<HTMLButtonElement | HTMLAnchorElement, ButtonProps>(
  (
    {
      variant = 'primary',
      size = 'm',
      disabled = false,
      loading = false,
      animated = false,
      iconLeft,
      iconRight,
      children,
      className,
      ...props
    },
    ref,
  ) => {
    const classes = cn(
      'button',
      `button--${variant}`,
      `button--${size}`,
      disabled && 'button--disabled',
      loading && 'button--loading',
      className,
    );

    const animateAttrs = animated
      ? { 'data-button-animate': '' }
      : {};

    const label = animated ? (
      <span className="button__label">
        <span className="button__label-inner">
          <span className="button__text is--default" data-button-text="">{children}</span>
          <span className="button__text is--hover" data-button-text="" aria-hidden="true">{children}</span>
        </span>
      </span>
    ) : (
      <span className="button__label">{children}</span>
    );

    const content = (
      <>
        {iconLeft && <span className="button__icon">{iconLeft}</span>}
        {label}
        {iconRight && <span className="button__icon">{iconRight}</span>}
        {loading && (
          <span className="button__spinner">
            <Spinner />
          </span>
        )}
      </>
    );

    if ('href' in props && props.href) {
      const isInactive = disabled || loading;
      return (
        <a
          ref={ref as React.Ref<HTMLAnchorElement>}
          className={classes}
          aria-disabled={isInactive || undefined}
          tabIndex={isInactive ? -1 : undefined}
          onClick={isInactive ? (e: React.MouseEvent) => e.preventDefault() : undefined}
          {...animateAttrs}
          {...(props as AnchorHTMLAttributes<HTMLAnchorElement>)}
        >
          {content}
        </a>
      );
    }

    return (
      <button
        ref={ref as React.Ref<HTMLButtonElement>}
        className={classes}
        disabled={disabled || loading}
        aria-busy={loading}
        {...animateAttrs}
        {...(props as ButtonHTMLAttributes<HTMLButtonElement>)}
      >
        {content}
      </button>
    );
  },
);

Button.displayName = 'Button';

/* -------------------------------------------------------------------------
   Button

   Sizing: explicit height + padding per size (shadcn/Radix convention).
   Gap, radius, icon-size remain em-relative for proportional scaling.

   Variants: primary, secondary, tertiary,
             destructive, destructive-secondary, destructive-tertiary
   Sizes:    xs, s, m (default), l, xl
   States:   enabled, hover, focus, active, disabled, loading
   ------------------------------------------------------------------------- */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5em;
  border-radius: 0.625em;
  border: 1px solid transparent;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-weight: var(--font-weight-medium);
  line-height: 1;
  width: auto;
  max-width: 100%;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  box-shadow: var(--shadow-none);
  transition:
    background-color var(--duration-300) var(--easing-out),
    color var(--duration-300) var(--easing-out),
    border-color var(--duration-300) var(--easing-out),
    scale var(--duration-500) cubic-bezier(0.32, 0.72, 0, 1);
  position: relative;
}

.button:active:not(.button--disabled):not(.button--loading) {
  scale: 0.955 0.925;
}

.button:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .button[data-button-animate]:hover:not(.button--disabled):not(.button--loading) {
    scale: 1.06 1.095;
  }
}

@media (prefers-reduced-motion: reduce) {
  .button {
    transition-duration: 0ms;
  }
  .button:active:not(.button--disabled) {
    scale: 1;
  }
}

/* ---- Sizes (same font-size, different height + padding) ---- */

.button--xs {
  height: var(--button-height-xs);
  padding: 0 var(--button-padding-x-xs);
  font-size: var(--button-font-size-all);
}

.button--s {
  height: var(--button-height-s);
  padding: 0 var(--button-padding-x-s);
  font-size: var(--button-font-size-all);
}

.button--m {
  height: var(--button-height-m);
  padding: 0 var(--button-padding-x-m);
  font-size: var(--button-font-size-all);
}

.button--l {
  height: var(--button-height-l);
  padding: 0 var(--button-padding-x-l);
  font-size: var(--button-font-size-all);
}

.button--xl {
  height: var(--button-height-xl);
  padding: 0 var(--button-padding-x-xl);
  font-size: var(--button-font-size-all);
}

/* ---- Variants ---- */

.button--primary {
  background-color: var(--button-bg-primary);
  color: var(--button-fg-primary);
}
.button--primary:hover:not(.button--disabled) {
  background-color: var(--button-hover-bg-primary);
}
.button--primary:active:not(.button--disabled) {
  background-color: var(--button-pressed-bg-primary);
}

.button--secondary {
  background-color: var(--button-bg-secondary);
  color: var(--button-fg-secondary);
  border-color: var(--button-border-secondary);
}
.button--secondary:hover:not(.button--disabled) {
  background-color: var(--button-hover-bg-secondary);
}
.button--secondary:active:not(.button--disabled) {
  background-color: var(--button-pressed-bg-secondary);
}

.button--tertiary {
  background-color: var(--button-bg-tertiary);
  color: var(--button-fg-tertiary);
}
.button--tertiary:hover:not(.button--disabled) {
  background-color: var(--button-hover-bg-tertiary);
}
.button--tertiary:active:not(.button--disabled) {
  background-color: var(--button-pressed-bg-tertiary);
}

.button--destructive-primary {
  background-color: var(--button-bg-destructive-primary);
  color: var(--button-fg-destructive-primary);
}
.button--destructive-primary:hover:not(.button--disabled) {
  background-color: var(--button-hover-bg-destructive-primary);
}
.button--destructive-primary:active:not(.button--disabled) {
  background-color: var(--button-pressed-bg-destructive-primary);
}

.button--destructive-secondary {
  background-color: var(--button-bg-destructive-secondary);
  color: var(--button-fg-destructive-secondary);
  border-color: var(--button-border-destructive-secondary);
}
.button--destructive-secondary:hover:not(.button--disabled) {
  background-color: var(--button-hover-bg-destructive-secondary);
}
.button--destructive-secondary:active:not(.button--disabled) {
  background-color: var(--button-pressed-bg-destructive-secondary);
}

.button--destructive-tertiary {
  background-color: var(--button-bg-destructive-tertiary);
  color: var(--button-fg-destructive-tertiary);
}
.button--destructive-tertiary:hover:not(.button--disabled) {
  background-color: var(--button-hover-bg-destructive-tertiary);
}
.button--destructive-tertiary:active:not(.button--disabled) {
  background-color: var(--button-pressed-bg-destructive-tertiary);
}

/* ---- States ---- */

.button--disabled {
  color: var(--button-disabled-fg-all);
  cursor: not-allowed;
  pointer-events: none;
}

.button--disabled.button--primary,
.button--disabled.button--secondary,
.button--disabled.button--destructive-primary,
.button--disabled.button--destructive-secondary {
  background-color: var(--muted);
  border-color: transparent;
}

.button--disabled.button--tertiary,
.button--disabled.button--destructive-tertiary {
  background-color: transparent;
  border-color: transparent;
}

.button--loading {
  cursor: wait;
  pointer-events: none;
}

.button--loading .button__label {
  opacity: 0;
}

.button--loading .button__spinner {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ---- Parts ---- */

.button__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.button__icon svg {
  width: 100%;
  height: 100%;
}

.button__label {
  display: inline-flex;
  align-items: center;
}


.button__spinner {
  display: none;
}

.button--loading .button__spinner {
  display: flex;
}

.button__spinner-icon {
  animation: button-spin var(--duration-700) linear infinite;
}

@keyframes button-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .button__spinner-icon {
    animation: none;
  }
}

/**
 * Text swap por caracter del boton (opt-in via data-button-animate).
 *
 * Vive en su propio partial porque lo consumen DOS entradas: button.css (y por
 * tanto atom.css/embed.css) y entries/webflow.css, que lo republica con las
 * clases prefijadas que usa el canal de Webflow. Una sola fuente: editar aqui
 * re-afina ambos artefactos.
 *
 * El JS solo parte el texto en .button__split-char (initButtonHover); TODA la
 * animacion es CSS, y usa cosas que el panel de estilos de Webflow no puede
 * expresar: curvas linear(), delays calc() por indice de caracter y filtros.
 */

/* ---- Animated text swap (opt-in via data-button-animate) ---- */

.button__label-inner {
  display: grid;
}

.button__text {
  grid-area: 1 / 1;
  will-change: transform;
}

.button__text.is--default .button__split-char {
  transition:
    translate 0.82s linear(0, 0.5737 7.6%, 0.8382 11.87%, 0.9463 14.19%, 1.0292 16.54%, 1.0886 18.97%, 1.1258 21.53%, 1.137 22.97%, 1.1424 24.48%, 1.1423 26.1%, 1.1366 27.86%, 1.1165 31.01%, 1.0507 38.62%, 1.0219 42.57%, 0.9995 46.99%, 0.9872 51.63%, 0.9842 58.77%, 1.0011 81.26%, 1),
    scale 0.82s linear(0, 0.5737 7.6%, 0.8382 11.87%, 0.9463 14.19%, 1.0292 16.54%, 1.0886 18.97%, 1.1258 21.53%, 1.137 22.97%, 1.1424 24.48%, 1.1423 26.1%, 1.1366 27.86%, 1.1165 31.01%, 1.0507 38.62%, 1.0219 42.57%, 0.9995 46.99%, 0.9872 51.63%, 0.9842 58.77%, 1.0011 81.26%, 1),
    opacity 0.15s ease-out,
    filter 0.15s ease-out;
}

.button__text.is--hover .button__split-char {
  opacity: 0;
  filter: blur(0.2em);
  translate: -1em 0 0;
  scale: 0.5;
  transition:
    translate 0.45s cubic-bezier(0.32, 0.72, 0, 1),
    scale 0.45s cubic-bezier(0.32, 0.72, 0, 1),
    opacity 0.15s 0.05s ease-out,
    filter 0.15s 0.05s ease-out;
}

.button__split-char {
  will-change: filter;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .button:is(:hover, :focus-visible) .button__text.is--default .button__split-char,
  .link-button:is(:hover, :focus-visible) .button__text.is--default .button__split-char,
  .toggle-group__item:is(:hover, :focus-visible) .button__text.is--default .button__split-char,
  [data-hover]:is(:hover, :focus-visible) :is(.button, .link-button, .toggle-group__item) .button__text.is--default .button__split-char {
    opacity: 0;
    filter: blur(5px);
    translate: 0.5em 0 0;
    scale: 0.5;
    transition:
      translate 0.45s calc((var(--char) - 1) * 0.018s) cubic-bezier(0.32, 0.72, 0, 1),
      scale 0.45s calc((var(--char) - 1) * 0.018s) cubic-bezier(0.32, 0.72, 0, 1),
      opacity 0.15s calc((var(--char) - 1) * 0.018s + 0.05s) ease-out,
      filter 0.15s calc((var(--char) - 1) * 0.018s + 0.05s) ease-out;
  }

  .button:is(:hover, :focus-visible) .button__text.is--hover .button__split-char,
  .link-button:is(:hover, :focus-visible) .button__text.is--hover .button__split-char,
  .toggle-group__item:is(:hover, :focus-visible) .button__text.is--hover .button__split-char,
  [data-hover]:is(:hover, :focus-visible) :is(.button, .link-button, .toggle-group__item) .button__text.is--hover .button__split-char {
    opacity: 1;
    filter: blur(0);
    translate: 0 0 0;
    scale: 1;
    transition:
      translate 0.82s calc((var(--char) - 1) * 0.018s + 0.05s) linear(0, 0.5737 7.6%, 0.8382 11.87%, 0.9463 14.19%, 1.0292 16.54%, 1.0886 18.97%, 1.1258 21.53%, 1.137 22.97%, 1.1424 24.48%, 1.1423 26.1%, 1.1366 27.86%, 1.1165 31.01%, 1.0507 38.62%, 1.0219 42.57%, 0.9995 46.99%, 0.9872 51.63%, 0.9842 58.77%, 1.0011 81.26%, 1),
      scale 0.82s calc((var(--char) - 1) * 0.018s + 0.05s) linear(0, 0.5737 7.6%, 0.8382 11.87%, 0.9463 14.19%, 1.0292 16.54%, 1.0886 18.97%, 1.1258 21.53%, 1.137 22.97%, 1.1424 24.48%, 1.1423 26.1%, 1.1366 27.86%, 1.1165 31.01%, 1.0507 38.62%, 1.0219 42.57%, 0.9995 46.99%, 0.9872 51.63%, 0.9842 58.77%, 1.0011 81.26%, 1),
      opacity 0.15s calc((var(--char) - 1) * 0.018s + 0.05s) ease-out,
      filter 0.15s calc((var(--char) - 1) * 0.018s + 0.05s) ease-out;
  }
}

/* ---- Variante estatica: el mismo boton, sin swap ----
   El equivalente declarativo del opt-out por atributo, para hosts donde el
   autor puede aplicar una clase pero no decidir si un atributo existe (Webflow:
   las props no pueden enlazarse a atributos, solo a visibility — verificado).
   Neutraliza las dos mitades del swap: esconde la capa de reemplazo y deja
   quieta la de por defecto en hover. */
.button.is--static .button__text.is--hover {
  display: none;
}

.button.is--static:is(:hover, :focus-visible) .button__text.is--default .button__split-char {
  opacity: 1;
  filter: none;
  translate: 0 0 0;
  scale: 1;
}

/**
 * Anillo de foco del botón, en su propio partial porque el canal de Webflow lo
 * necesita y el panel de estilos no puede declararlo: un box-shadow compuesto
 * con dos var() se parsea como una sola variable y pierde la geometría.
 *
 * Doble anillo (superficie + contraste) para que se vea sobre cualquier fondo,
 * incluido el propio color del botón. Ambos colores salen de tokens.
 *
 * Solo `:focus-visible`: el foco de ratón no debe pintar anillo.
 */
.button:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 var(--stroke-medium) var(--background),
    0 0 0 calc(var(--stroke-medium) * 2) var(--ring);
}
